// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;
    Log logContract;

    function setUp() public {
        logContract = new Log();
        c = new Private_Bank(address(logContract));
    }

    function testFuzz_property(uint256 amount, uint256 depositAmount, address actor) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Keep params in admissible wide domain
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        // Deposit must be strictly greater than MinDeposit (1 ether)
        depositAmount = bound(depositAmount, 1 ether + 1, 100 ether);
        // Withdraw must be positive, at most the deposited amount, and less than deposit to make balance strictly decrease
        amount = bound(amount, 1, depositAmount - 1);

        vm.deal(actor, depositAmount + 1 ether);

        // Record prior balance for actor; it starts at 0
        uint256 balanceBefore = c.balances(actor);

        // Deposit into c as actor; this sets balances[actor] = depositAmount
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 balanceAfterDeposit = c.balances(actor);
        // Sanity: deposit should have taken effect
        assertTrue(balanceAfterDeposit > balanceBefore);

        // Now CashOut as actor; use try/catch to handle potential revert
        bool ok;
        vm.prank(actor);
        try c.CashOut(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfterCashOut = c.balances(actor);

        // General rule: after CashOut with 0 < amount < balanceBefore, the stored balance must be strictly less than before
        // because the correct contract subtracts amount, while the mutant adds amount, increasing it.
        assertTrue(
            !ok || balanceAfterCashOut < balanceAfterDeposit,
            "CashOut must not increase caller balance"
        );
    }
}
